// Upserts a reading session (id generated by the client). Feeds streaks and stats.
import { sql } from "drizzle-orm";
import { getDb, readingSessions } from "@/lib/db";
import { currentUser } from "@/lib/session";

export const runtime = "nodejs";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const userId = await currentUser();
  if (!userId) return new Response("Unauthorized", { status: 401 });
  const bookId = Number((await params).id);

  const b = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const id = String(b?.id ?? "");
  const localDate = String(b?.localDate ?? "");
  const startedAt = new Date(String(b?.startedAt));
  const endedAt = new Date(String(b?.endedAt));
  const startPage = Math.max(1, Math.floor(Number(b?.startPage)) || 1);
  const endPage = Math.max(1, Math.floor(Number(b?.endPage)) || 1);
  const pagesRead = Math.max(0, Math.floor(Number(b?.pagesRead)) || 0);
  if (!UUID.test(id) || !DATE.test(localDate) || isNaN(+startedAt) || isNaN(+endedAt) || endedAt < startedAt) {
    return new Response("Bad request", { status: 400 });
  }

  await getDb()
    .insert(readingSessions)
    .values({ id, userId, bookId, localDate, startedAt, endedAt, startPage, endPage, pagesRead })
    .onConflictDoUpdate({
      target: readingSessions.id,
      set: {
        endedAt: sql`greatest(${readingSessions.endedAt}, ${endedAt.toISOString()}::timestamptz)`,
        endPage,
        pagesRead: sql`greatest(${readingSessions.pagesRead}, ${pagesRead})`,
      },
      setWhere: sql`${readingSessions.userId} = ${userId}`,
    });
  return new Response(null, { status: 204 });
}
